    );
}

import { prisma } from "@/lib/prisma";
import { comparePassword, signToken } from "@/lib/auth";
import { NextResponse } from "next/server";

export async function POST(req: Request) {
    try {
        const { email, password } = await req.json();
        const user = await prisma.user.findUnique({ where: { email } });
        if (!user || !(await comparePassword(password, user.password))) {
            return NextResponse.json({ error: "Invalid credentials" }, { status: 401 });
        }

        const token = signToken({ id: user.id, role: user.role });
        return NextResponse.json({ token, user: { id: user.id, email: user.email, role: user.role } });
    } catch (error) {
        return NextResponse.json({ error: "ERR" }, { status: 500 });
    }
}

import { prisma } from "@/lib/prisma";
import { hashPassword, signToken } from "@/lib/auth";
import { NextResponse } from "next/server";

export async function POST(req: Request) {
    try {
        const { name, email, password } = await req.json();
        const existing = await prisma.user.findUnique({ where: { email } });
        if (existing) return NextResponse.json({ error: "User exists" }, { status: 400 });

        const hashedPassword = await hashPassword(password);
        const user = await prisma.user.create({
            data: { 
                name,
                email, 
                password: hashedPassword,
                role: "OWNER", // First user is owner
                projects: {
                    create: {
                        name: "My First Project"
                    }
                }
            }
        });

        const token = signToken({ id: user.id, role: user.role });
        return NextResponse.json({ token, user: { id: user.id, email: user.email, role: user.role } });
    } catch (error) {
        return NextResponse.json({ error: "ERR" }, { status: 500 });
    }
}

import { createRedisClient } from "@/lib/redis";
import { NextResponse } from "next/server";
import { Ratelimit } from "@upstash/ratelimit";
import { ChatRequestSchema } from "@/lib/validation";
import { OrchestratorService } from "@/lib/services/orchestrator";
import { withObservability } from "@/lib/middleware/observability";
import { logContext } from "@/lib/logger";
import { searchProducts, getProduct } from "@/lib/woocommerce";
import { getCart, addToCart } from "@/lib/cart";
import { generateProductComparison } from "@/lib/commerce/comparison";
import { trackActivity } from "@/lib/sales/session";

export const dynamic = "force-dynamic";

let ratelimit: Ratelimit | null = null;
const _redisForRateLimit = createRedisClient();
if (_redisForRateLimit) {
    ratelimit = new Ratelimit({
        redis: _redisForRateLimit,
        limiter: Ratelimit.slidingWindow(20, "1 m"),
    });
}

interface ToolResult {
    text: string;
    data?: any;
    intent: string;
}

async function runTool(
    intent: any,
    userMessage: string,
    project: any,
    customerId: string
): Promise<ToolResult> {
    const { entities } = intent;
    const wcConfig = {
        storeUrl: project.wooCommerceStoreUrl || "",
        consumerKey: project.wooCommerceKey || "",
        consumerSecret: project.wooCommerceSecret || "",
    };

    try {
        switch (intent.intent) {
            case "product_search": {
                const query = entities.product_query ?? userMessage;
                const products = await searchProducts(query, wcConfig);
                if (!products.length) return { text: "No products found matching your query.", intent: "product_search" };

                return {
                    text: "I found these items for you:",
                    data: { type: "product_list", products: products.map(p => ({
                        id: p.id,
                        name: p.name,
                        price: p.price,
                        image: p.images?.[0]?.src,
                        stock_status: p.stock_status,
                    })) },
                    intent: "product_search"
                };
            }

            case "cart_add": {
                const query = entities.product_query ?? userMessage;
                const pid = entities.product_id;

                let product;
                if (pid) {
                    product = await getProduct(Number(pid), wcConfig);
                } else {
                    const search = await searchProducts(query, wcConfig);
                    product = search[0];
                }

                if (!product) return { text: "I couldn't find that product to add to your cart.", intent: "cart_add" };

                const cart = await addToCart(project.id, customerId, {
                    productId: product.id,
                    name: product.name,
                    price: parseFloat(product.price),
                    quantity: entities.quantity || 1,
                    image: product.images?.[0]?.src
                });

                return {
                    text: `✅ Added *${product.name}* to your cart. Total: **${cart.subtotal.toFixed(2)}**.`,
                    data: { type: "cart_update", cart },
                    intent: "cart_add"
                };
            }

            case "cart_view": {
                const cart = await getCart(project.id, customerId);
                if (!cart.items.length) return { text: "Your cart is empty.", intent: "cart_view" };
                return {
                    text: `🛒 **Your Cart** Total: **${cart.subtotal.toFixed(2)}**.`,
                    data: { type: "cart_summary", cart },
                    intent: "cart_view"
                };
            }

            case "comparison_request": {
                const query = entities.product_query ?? userMessage;
                // Simple heuristic: search for top 2 matches to compare
                const products = await searchProducts(query, wcConfig);
                if (products.length < 2) return { text: "I need at least two products to compare.", intent: "comparison_request" };

                const comparison = await generateProductComparison(products[0].id, products[1].id, wcConfig);
                if (!comparison) return { text: "I couldn't generate a comparison at this time.", intent: "comparison_request" };

                // Track comparison event
                trackActivity(customerId, "compare", { productIds: [products[0].id, products[1].id] });

                return {
                    text: `Here is a comparison between **${products[0].name}** and **${products[1].name}**:`,
                    data: { type: "product_comparison", comparison },
                    intent: "comparison_request"
                };
            }

            default:
                return { text: "", intent: "general" };
        }
    } catch (err) {
        console.error(`[CHAT] Tool execution failed`, err);
        return { text: "I encountered a technical issue.", intent: intent.intent };
    }
}


export async function POST(req: Request) {
    const correlationId = req.headers.get("x-correlation-id");

    return await withObservability(correlationId, async () => {
        try {
            if (ratelimit) {
                const ip = req.headers.get("x-forwarded-for") ?? "anon";
                const { success } = await ratelimit.limit(ip);
                if (!success) return NextResponse.json({ error: "Too many requests" }, { status: 429 });
            }

            const body = await req.json();
            const validation = ChatRequestSchema.safeParse(body);

            if (!validation.success) {
                return NextResponse.json({ error: "Invalid request", details: validation.error.format() }, { status: 400 });
            }

            const { message, messages = [], projectId, userId } = validation.data;
            const sessionId = "web_session"; 

            const result = await OrchestratorService.process({
                projectId,
                userId,
                sessionId,
                channel: "web",
                message: message || messages[messages.length - 1]?.content || "",
                metadata: { correlationId: (logContext.getStore() as any)?.correlationId }
            });

            return NextResponse.json(result);
        } catch (error) {
            console.error("Internal API error:", error);
            return NextResponse.json({ error: "Internal Error" }, { status: 500 });
        }
    });
}

import { NextRequest } from "next/server";
import { omniBus, OmniEvent } from "@/lib/events";

export const dynamic = "force-dynamic";

export async function GET(req: NextRequest) {
    const sessionId = req.nextUrl.searchParams.get("sessionId");

    if (!sessionId) {
        return new Response("Missing sessionId", { status: 400 });
    }

    let controller: ReadableStreamDefaultController;
    const stream = new ReadableStream({
        start(c) {
            controller = c;
        },
        cancel() {
            // Cleanup logic when client disconnects
            omniBus.removeListener(OmniEvent.AUTONOMOUS_MESSAGE_GENERATED, messageListener);
        }
    });

    const messageListener = (payload: any) => {
        if (payload.sessionId === sessionId) {
            const data = JSON.stringify({
                content: payload.message,
                data: payload.data,
                intent: "autonomous_intervention"
            });
            controller.enqueue(`data: ${data}\n\n`);
        }
    };

    omniBus.on(OmniEvent.AUTONOMOUS_MESSAGE_GENERATED, messageListener);

    // Keep-alive to prevent connection timeout
    const keepAlive = setInterval(() => {
        try {
            controller.enqueue(`: ping\n\n`);
        } catch {
            clearInterval(keepAlive);
        }
    }, 15000);

    req.signal.addEventListener("abort", () => {
        clearInterval(keepAlive);
        omniBus.removeListener(OmniEvent.AUTONOMOUS_MESSAGE_GENERATED, messageListener);
    });

    return new Response(stream, {
        headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache, no-transform",
            "Connection": "keep-alive",
        },
    });
}

import { verifyToken } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { AnalyticsService } from "@/lib/services/analytics";
import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";

function getToken(req: Request) {
    const auth = req.headers.get("authorization") || "";
    return auth.replace("Bearer ", "");
}

export async function GET(req: Request) {
    try {
        const payload = verifyToken(getToken(req)) as { id: string };

        // Find the user's primary project
        const project = await prisma.project.findFirst({
            where: { userId: payload.id },
            orderBy: { createdAt: "desc" },
        });

        if (!project) {
            return NextResponse.json({ error: "No project found" }, { status: 404 });
        }

        const stats = await AnalyticsService.getProjectStats(project.id);

        return NextResponse.json(stats);
    } catch (err) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
}

import { prisma } from "@/lib/prisma";
import { verifyToken } from "@/lib/auth";
import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";

function getToken(req: Request) {
    return (req.headers.get("authorization") || "").replace("Bearer ", "");
}

// GET — paginated conversation logs for a user
export async function GET(req: Request) {
    try {
        const payload = verifyToken(getToken(req)) as { id: string };
        const { searchParams } = new URL(req.url);
        const projectId = searchParams.get("projectId");
        const take = parseInt(searchParams.get("take") || "20");
        const skip = parseInt(searchParams.get("skip") || "0");

        const where: any = { project: { userId: payload.id } };
        if (projectId) where.projectId = projectId;

        const [conversations, total] = await Promise.all([
            prisma.conversation.findMany({
                where,
                orderBy: { createdAt: "desc" },
                take,
                skip,
                include: { project: { select: { name: true } } },
            }),
            prisma.conversation.count({ where }),
        ]);

        return NextResponse.json({ conversations, total });
    } catch {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
}

import { groq } from "@/lib/groq";
import { prisma } from "@/lib/prisma";
import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";

export async function POST(req: Request) {
    try {
        const apiKey = req.headers.get("x-api-key");
        if (!apiKey) return NextResponse.json({ error: "Missing API Key" }, { status: 401 });

        const project = await prisma.project.findUnique({
            where: { apiKey },
            include: { user: true }
        });

        if (!project) return NextResponse.json({ error: "Invalid API Key" }, { status: 401 });

        const { messages, userId = "anonymous" } = await req.json();

        const knowledge = await prisma.knowledge.findMany({
            where: { projectId: project.id },
            take: 3
        });

        const kbContent = knowledge.map((k: any) => k.content).join("\n");

        const response = await groq.chat.completions.create({
            model: "llama-3.3-70b-versatile",
            messages: [
                { role: "system", content: `Concise. Knowledge: ${kbContent}` },
                ...messages.slice(-3)
            ],
            max_completion_tokens: 200,
        });

        const content = response.choices[0].message.content;
        const tokens = response.usage?.total_tokens || 0;

        await prisma.$transaction([
            prisma.conversation.create({
                data: { projectId: project.id, userId, message: messages[messages.length - 1].content, response: content || "" }
            }),
            prisma.usage.create({
                data: { projectId: project.id, tokens }
            })
        ]);

        return NextResponse.json({ content, usage: { tokens } });
    } catch (error) {
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

import { stripe } from "@/lib/stripe";
import { prisma, projectContext } from "@/lib/prisma";
import { NextResponse } from "next/server";
import { headers } from "next/headers";
import { createOrder, WooCommerceConfig } from "@/lib/woocommerce";
import { advanceCheckoutStage } from "@/lib/checkout";
import { sendWhatsAppMessage } from "@/lib/whatsapp";
import { logger } from "@/lib/logger";

import { withEventIdempotency } from "@/lib/events/idempotency";

export async function POST(req: Request) {
    const body = await req.text();
    const sig = (await headers()).get("stripe-signature");

    if (!sig) return NextResponse.json({ error: "Missing signature" }, { status: 400 });

    try {
        const event = stripe.webhooks.constructEvent(body, sig, process.env.STRIPE_WEBHOOK_SECRET!);
        logger.info(`[STRIPE] Received event: ${event.type}`, { eventId: event.id });

        if (event.type === "checkout.session.completed") {
            const session = event.data.object as any;
            const metadata = session.metadata;

            if (metadata.type === "commerce_checkout") {
                await withEventIdempotency(event.id, "stripe_checkout", async () => {
                    await handleCommerceCheckout(session);
                });
            } else {
                await handleSubscriptionUpgrade(session);
            }
        }

        return NextResponse.json({ received: true });
    } catch (err: any) {
        logger.error("[STRIPE] Webhook error", { error: err.message });
        return NextResponse.json({ error: err.message }, { status: 400 });
    }
}

async function handleCommerceCheckout(session: any) {
    const { projectId, customerId, cartId } = session.metadata;

    await projectContext.run({ projectId }, async () => {
        const project = await prisma.project.findUnique({
            where: { id: projectId },
            include: { user: true }
        });

        if (!project) throw new Error(`Project ${projectId} not found`);

        const cart = await prisma.cart.findUnique({
            where: { id: cartId },
            include: { items: true, customer: true }
        });

        if (!cart) throw new Error(`Cart ${cartId} not found`);

        const wcConfig: WooCommerceConfig = {
            storeUrl: project.wooCommerceStoreUrl || "",
            consumerKey: project.wooCommerceKey || "",
            consumerSecret: project.wooCommerceSecret || "",
        };

        // 1. Create WooCommerce Order
        const wcOrder = await createOrder({
            customer: {
                name: cart.customer.name || "Customer",
                email: cart.customer.email || "",
                phone: cart.customer.phone,
                address: cart.customer.address || "N/A",
                city: cart.customer.city || "N/A",
                country: "US" // Default or extract from shipping info
            },
            items: cart.items.map(item => ({
                productId: item.productId,
                quantity: item.quantity
            })),
            paymentMethod: "stripe"
        }, wcConfig, `stripe_${session.id}`);

        if (!wcOrder) {
            logger.error(`[COMMERCE] Failed to create WC order for session ${session.id}`);
            // In production, we should queue this for retry
            throw new Error("WooCommerce order creation failed");
        }

        // 2. Advance FSM to CONFIRMED
        const checkout = await prisma.checkoutSession.findFirst({
            where: { projectId, customerId, cartId, status: "pending" }
        });

        if (checkout) {
            await advanceCheckoutStage(checkout.id, "CONFIRMED", { 
                paymentId: session.id,
                orderId: wcOrder.id 
            });
        }

        // 3. Mark Cart as Converted
        await prisma.cart.update({
            where: { id: cartId },
            data: { status: "converted" }
        });

        // 4. Send Confirmation Notification (WhatsApp)
        if (project.whatsappEnabled) {
            const message = `🎉 Thank you for your order! Your Order #${wcOrder.id} has been confirmed. We'll notify you when it ships.`;
            await sendWhatsAppMessage(cart.customer.phone, message, {
                token: project.whatsappToken || "",
                phoneId: project.whatsappPhoneId || "",
                verifyToken: project.whatsappVerifyToken || ""
            });
        }

        logger.info(`[COMMERCE] Checkout completed successfully`, { 
            projectId, customerId, cartId, wcOrderId: wcOrder.id 
        });
    });
}

async function handleSubscriptionUpgrade(session: any) {
    const { userId, plan } = session.metadata;
    if (!userId || !plan) return;

    await prisma.user.update({
        where: { id: userId },
        data: { plan, stripeId: session.customer }
    });
    logger.info(`[STRIPE] Subscription upgraded`, { userId, plan });
}

import { NextResponse } from "next/server";
import twilio from "twilio";
import { prisma } from "@/lib/prisma";
import { OrchestratorService } from "@/lib/services/orchestrator";
import { logger } from "@/lib/logger";

export const dynamic = "force-dynamic";

export async function POST(req: Request, { params }: { params: Promise<{ projectId: string }> }) {
    const { projectId } = await params;

    const formData = await req.formData();
    const speechResult = formData.get("SpeechResult")?.toString() || "";
    const fromNumber = formData.get("From")?.toString() || "Unknown";

    const twiml = new twilio.twiml.VoiceResponse();

    if (!speechResult.trim()) {
        twiml.say("I didn't quite catch that. Could you repeat?");
        twiml.gather({
            input: ['speech'],
            action: `/api/webhooks/twilio/${projectId}/process`,
            speechTimeout: "auto"
        });
        return new NextResponse(twiml.toString(), { headers: { "Content-Type": "text/xml" } });
    }

    try {
        const sessionId = `twilio:${fromNumber}`;
        const correlationId = `twilio:${projectId}:${fromNumber}:${Date.now()}`;

        // Process through the standard Orchestrator
        const result = await OrchestratorService.process({
            projectId,
            userId: fromNumber,
            sessionId,
            channel: "voice", // could be mapped to 'web' or handled specifically
            message: speechResult,
            metadata: { correlationId }
        });

        // Strip markdown from response for TTS
        let cleanText = result.content.replace(/[*#_`~\[\]>]/g, "").trim();

        twiml.say(cleanText);
        twiml.gather({
            input: ['speech'],
            action: `/api/webhooks/twilio/${projectId}/process`,
            speechTimeout: "auto"
        });

    } catch (err) {
        logger.error("[TWILIO] Error processing voice input", { error: err });
        twiml.say("I'm sorry, I'm having trouble processing that right now.");
        twiml.hangup();
    }

    return new NextResponse(twiml.toString(), {
        headers: { "Content-Type": "text/xml" }
    });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import {
    parseInboundMessage,
    verifyWebhook,
    verifySignature,
    sendWhatsAppMessage,
} from "@/lib/whatsapp";
import { logger } from "@/lib/logger";
import { OrchestratorService } from "@/lib/services/orchestrator";
import { withObservability } from "@/lib/middleware/observability";

export const dynamic = "force-dynamic";

async function getProjectConfig(projectId: string) {
    const project = await prisma.project.findUnique({ where: { id: projectId } });
    if (!project) return null;
    return {
        token: project.whatsappToken || "",
        phoneId: project.whatsappPhoneId || "",
        verifyToken: project.whatsappVerifyToken || "omnichat_verify",
        appSecret: project.whatsappAppSecret,
        wooCommerceConfig: {
            storeUrl: project.wooCommerceStoreUrl || "",
            consumerKey: project.wooCommerceKey || "",
            consumerSecret: project.wooCommerceSecret || "",
        }
    };
}

export async function GET(req: Request, { params }: { params: Promise<{ projectId: string }> }) {
    const { projectId } = await params;
    const config = await getProjectConfig(projectId);
    if (!config) return new Response("Project not found", { status: 404 });

    const { searchParams } = new URL(req.url);
    const challenge = verifyWebhook(Object.fromEntries(searchParams.entries()), config);

    if (challenge !== null) return new Response(challenge, { status: 200 });
    return new Response("Forbidden", { status: 403 });
}

export async function POST(req: Request, { params }: { params: Promise<{ projectId: string }> }) {
    const { projectId } = await params;
    const config = await getProjectConfig(projectId);
    if (!config) return new Response("Project not found", { status: 404 });

    const rawBody = await req.text();
    const signature = req.headers.get("x-hub-signature-256");
    const valid = await verifySignature(rawBody, signature, config);
    if (!valid) return new Response("Unauthorized", { status: 401 });

    let body: any;
    try {
        body = JSON.parse(rawBody);
    } catch {
        return new Response("Bad Request", { status: 400 });
    }

    const inbound = parseInboundMessage(body);
    if (!inbound) return new Response("OK", { status: 200 });

    processMessage(projectId, inbound, config).catch((err) =>
        logger.error("WhatsApp message processing error", { error: err })
    );

    return new Response("OK", { status: 200 });
}

async function processMessage(projectId: string, inbound: any, config: any): Promise<void> {
    const { from, text } = inbound;
    const sessionId = `wa:${from}`;
    const correlationId = `wa:${projectId}:${from}:${Date.now()}`;

    if (text && text.trim().startsWith("LINK-")) {
        const code = text.trim();
        try {
            const { createRedisClient } = await import("@/lib/redis");
            const redis = createRedisClient();
            if (redis) {
                const handoffData = await redis.get(`handoff:${code}`);
                if (handoffData) {
                    const parsed = typeof handoffData === "string" ? JSON.parse(handoffData) : handoffData;

                    await prisma.customer.update({
                        where: { id: parsed.customerId },
                        data: { phone: from }
                    });

                    await redis.del(`handoff:${code}`);
                    await sendWhatsAppMessage(from, "✅ Session transferred successfully! Your web context is now synced.", config);
                    return;
                }
            }
            await sendWhatsAppMessage(from, "Sorry, this handoff code is invalid or has expired.", config);
            return;
        } catch (err) {
            logger.error("[HANDOFF] Failed to link session", { error: err });
            await sendWhatsAppMessage(from, "Sorry, there was an error transferring your session.", config);
            return;
        }
    }

    return await withObservability(correlationId, async () => {
        try {
            const result = await OrchestratorService.process({
                projectId,
                userId: from,
                sessionId,
                channel: "whatsapp",
                message: text,
                metadata: { correlationId }
            });

            await sendWhatsAppMessage(from, result.content, config);
        } catch (err) {
            logger.error("[WHATSAPP] Failed to process message via orchestrator", { error: err, from, projectId });
            await sendWhatsAppMessage(from, "I'm sorry, I'm having trouble processing your request right now.", config);
        }
    });
}

import { NextRequest, NextResponse } from "next/server";
import { createHmac } from "crypto";
import { prisma, projectContext } from "@/lib/prisma";
import { omniBus, OmniEvent } from "@/lib/events";
import { createRedisClient } from "@/lib/redis";

/**
 * WooCommerce Webhook Handler
 * 
 * Replaces the previous polling-based inventory sync with a real-time
 * push model. WooCommerce sends signed HTTP POST events to this endpoint
 * whenever products, orders, or inventory change.
 * 
 * Setup:
 *   WooCommerce Admin → Settings → Advanced → Webhooks → Add Webhook
 *   Delivery URL: https://<your-domain>/api/webhooks/woocommerce
 *   Secret: <WC_WEBHOOK_SECRET env var>
 * 
 * Topics handled:
 *   - product.updated  → Invalidate Redis product cache
 *   - product.created  → Invalidate Redis product cache
 *   - order.created    → Sync order status to DB
 *   - order.updated    → Sync order status to DB
 */

const WC_WEBHOOK_SECRET = process.env.WC_WEBHOOK_SECRET || "";

function verifyWooCommerceSignature(body: string, signature: string): boolean {
    if (!WC_WEBHOOK_SECRET) return true; // Skip in dev without secret
    const expected = createHmac("sha256", WC_WEBHOOK_SECRET)
        .update(body, "utf8")
        .digest("base64");
    return expected === signature;
}

function getCacheKeyPrefix(storeUrl: string): string {
    return `wc:${Buffer.from(storeUrl).toString("base64")}:search:`;
}

export async function POST(req: NextRequest) {
    const rawBody = await req.text();
    const signature = req.headers.get("x-wc-webhook-signature") || "";
    const topic = req.headers.get("x-wc-webhook-topic") || "";
    const webhookId = req.headers.get("x-wc-webhook-id") || "unknown";
    const deliveryId = req.headers.get("x-wc-delivery-id") || "unknown";

    // 1. Verify signature
    if (!verifyWooCommerceSignature(rawBody, signature)) {
        console.error(`[WC-WEBHOOK] Invalid signature for delivery ${deliveryId}`);
        return NextResponse.json({ error: "Invalid signature" }, { status: 401 });
    }

    let payload: any;
    try {
        payload = JSON.parse(rawBody);
    } catch {
        return NextResponse.json({ error: "Invalid JSON payload" }, { status: 400 });
    }

    console.log(`[WC-WEBHOOK] Received topic=${topic} webhookId=${webhookId}`);

    const redis = createRedisClient();

    try {
        // 2. Handle product changes — invalidate cache keys
        if (topic === "product.updated" || topic === "product.created") {
            if (redis && payload.id) {
                // Invalidate any cached search results that might include this product.
                // We can't know which search keys are stale, so we scan for the prefix pattern.
                // In production, use Redis SCAN with pattern matching.
                const productId = payload.id;
                const storeUrl = process.env.WOOCOMMERCE_STORE_URL || "";
                if (storeUrl) {
                    const prefix = getCacheKeyPrefix(storeUrl);
                    console.log(`[WC-WEBHOOK] Invalidating search cache for product ${productId}`);
                    // Bust the specific product cache key
                    await redis.del(`wc:product:${productId}`);
                }
            }

            // Emit internal event for downstream listeners
            await omniBus.emitOmni(OmniEvent.ANALYTICS_TRACK, {
                type: "wc_product_sync",
                productId: payload.id,
                name: payload.name,
                stockStatus: payload.stock_status,
                stockQuantity: payload.stock_quantity,
                price: payload.price,
            });

            return NextResponse.json({ received: true, action: "cache_invalidated" });
        }

        // 3. Handle order changes — sync status to DB
        if (topic === "order.created" || topic === "order.updated") {
            const wcOrderId = payload.id;
            const wcStatus = payload.status;

            if (wcOrderId) {
                // Look up if we have a matching CheckoutSession for this order
                // Orders injected by OmniChat store the idempotency key in meta_data
                const idempotencyMeta = (payload.meta_data || []).find(
                    (m: { key: string; value: string }) => m.key === "_omnichat_idempotency_key"
                );

                if (idempotencyMeta?.value) {
                    const sessionRecord = await prisma.checkoutSession.findFirst({
                        where: { orderId: wcOrderId.toString() },
                        select: { id: true, projectId: true },
                    });

                    if (sessionRecord) {
                        // Run update inside the correct project context
                        await projectContext.run({ projectId: sessionRecord.projectId }, async () => {
                            await prisma.checkoutSession.update({
                                where: { id: sessionRecord.id },
                                data: { 
                                    status: wcStatus === "completed" ? "COMPLETED" : 
                                            wcStatus === "processing" ? "PROCESSING" :
                                            wcStatus === "cancelled" ? "CANCELLED" : "PENDING"
                                },
                            });
                        });

                        console.log(`[WC-WEBHOOK] Synced order #${wcOrderId} → status: ${wcStatus}`);

                        if (wcStatus === "completed") {
                            await omniBus.emitOmni(OmniEvent.ORDER_CREATED, {
                                wcOrderId,
                                status: wcStatus,
                                total: payload.total,
                            });
                        }
                    }
                }
            }

            return NextResponse.json({ received: true, action: "order_synced" });
        }

        // 4. Acknowledge unhandled topics gracefully
        return NextResponse.json({ received: true, action: "no_op", topic });

    } catch (err: any) {
        console.error(`[WC-WEBHOOK] Error processing topic=${topic}:`, err.message);
        // Return 200 to prevent WooCommerce from retrying indefinitely
        return NextResponse.json({ received: true, error: "Processing error, logged" });
    }
}

