import { useEffect, useRef } from "react";
import gsap from "gsap";

interface CanvasSequenceOptions {
  frameCount: number;
  getFrameUrl: (index: number) => string;
  lerpScroll?: number;
  lerpFrame?: number;
}

/**
 * Ultra-smooth Apple-style Canvas Image Sequence Engine.
 * 
 * Optimized for Mobile/Low-End devices:
 * 1. Lazy Progressive Preloading (First 5 frames unblock render).
 * 2. Render Caching (Only draw if frame changes).
 * 3. Debounced Resizing.
 * 4. GSAP Ticker for frame-perfect sync.
 */
export function useCanvasSequence(
  canvasRef: React.RefObject<HTMLCanvasElement | null>,
  {
    frameCount,
    getFrameUrl,
    lerpScroll = 0.05,
    lerpFrame = 0.12,
  }: CanvasSequenceOptions
) {
  const images = useRef<HTMLImageElement[]>([]);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const targetFrame = useRef(0);
  const smoothFrame = useRef(0);
  const isReady = useRef(false);
  const lastDrawnFrame = useRef(-1);

  useEffect(() => {
    // Disable heavy canvas animations on mobile devices
    if (typeof window !== "undefined" && window.innerWidth < 768) return;

    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext("2d", { alpha: false });
    if (!ctx) return;

    // 1. Progressive Preload Strategy
    const INITIAL_FRAMES = Math.min(5, frameCount);
    let loadedCount = 0;

    const loadFrame = (i: number, isInitial: boolean) => {
      const img = new Image();
      img.src = getFrameUrl(i);
      img.onload = () => {
        if (isInitial) {
          loadedCount++;
          if (loadedCount === INITIAL_FRAMES) {
            isReady.current = true;
            // Unblock rendering, then lazy load the rest in background
            if (INITIAL_FRAMES < frameCount) {
              requestIdleCallback ? requestIdleCallback(loadRemaining) : setTimeout(loadRemaining, 100);
            }
          }
        }
      };
      images.current[i - 1] = img;
    };

    const loadRemaining = () => {
      for (let i = INITIAL_FRAMES + 1; i <= frameCount; i++) {
        loadFrame(i, false);
      }
    };

    for (let i = 1; i <= INITIAL_FRAMES; i++) {
      loadFrame(i, true);
    }

    // 2. High DPI Scaling with Debounce
    let resizeTimer: NodeJS.Timeout;
    let canvasWidth = window.innerWidth;
    let canvasHeight = window.innerHeight;

    const resizeCanvas = () => {
      const dpr = window.devicePixelRatio || 1;
      canvasWidth = window.innerWidth;
      canvasHeight = window.innerHeight;

      canvas.width = canvasWidth * dpr;
      canvas.height = canvasHeight * dpr;
      canvas.style.width = `${canvasWidth}px`;
      canvas.style.height = `${canvasHeight}px`;
      ctx.scale(dpr, dpr);
      lastDrawnFrame.current = -1; // Force redraw on resize
    };

    const onResize = () => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(resizeCanvas, 150);
    };

    window.addEventListener("resize", onResize);
    resizeCanvas(); // Initial execution

    // 3. Scroll Listener
    const onScroll = () => {
      const scrollTop = window.scrollY;
      const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
      if (maxScroll > 0) {
        targetProgress.current = Math.min(Math.max(scrollTop / maxScroll, 0), 1);
      }
    };

    window.addEventListener("scroll", onScroll, { passive: true });

    // 4. Master Animation Loop (GSAP Ticker)
    const render = () => {
      if (!isReady.current) return;

      currentProgress.current += (targetProgress.current - currentProgress.current) * lerpScroll;
      targetFrame.current = currentProgress.current * (frameCount - 1);
      smoothFrame.current += (targetFrame.current - smoothFrame.current) * lerpFrame;

      const frameIndex = Math.round(smoothFrame.current);

      // Optimization: Only render if frame actually changed!
      if (frameIndex === lastDrawnFrame.current) return;

      const img = images.current[frameIndex];

      if (img && img.complete) {
        const imgWidth = img.width;
        const imgHeight = img.height;
        const ratio = Math.max(canvasWidth / imgWidth, canvasHeight / imgHeight);
        const newWidth = imgWidth * ratio;
        const newHeight = imgHeight * ratio;
        const x = (canvasWidth - newWidth) / 2;
        const y = (canvasHeight - newHeight) / 2;

        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        ctx.drawImage(img, x, y, newWidth, newHeight);

        lastDrawnFrame.current = frameIndex;
      }
    };

    gsap.ticker.add(render);

    return () => {
      gsap.ticker.remove(render);
      window.removeEventListener("resize", onResize);
      window.removeEventListener("scroll", onScroll);
      clearTimeout(resizeTimer);
    };
  }, [canvasRef, frameCount, getFrameUrl, lerpScroll, lerpFrame]);
}

import { useEffect, useRef } from "react";
import gsap from "gsap";

/**
 * Ultra-smooth cinematic video scrub engine.
 *
 * Architecture: decoupled double-lerp via GSAP ticker
 *
 *   [user scroll] ──→ targetScrollProgress (raw, instant)
 *        ↓ lerp 1 (factor 0.05, heavy damping)
 *   currentScrollProgress (virtual cinematic scroll)
 *        ↓ multiply by duration
 *   targetVideoTime
 *        ↓ lerp 2 (factor 0.12, catches up to scroll)
 *   smoothVideoTime → video.currentTime
 *
 * The two-stage lerp is what separates cinematic motion from choppy scrubbing.
 * Layer 1 smooths the SCROLL feel (heavy inertia).
 * Layer 2 smooths the VIDEO SEEK (prevents hard frame jumps from browser decode lag).
 *
 * GSAP ticker is used as the master loop because:
 * - It handles tab-visibility pausing automatically
 * - It runs inside the same RAF frame as Lenis (when co-ticked)
 * - It uses lagSmoothing(0) to avoid huge jumps after tab switch
 */
export function useVideoScrub(
    videoRef: React.RefObject<HTMLVideoElement | null>,
    lenisRef?: React.RefObject<any>
) {
    // All animation state is in refs — zero React re-renders during playback
    const targetScrollProgress = useRef(0);
    const currentScrollProgress = useRef(0);
    const targetVideoTime = useRef(0);
    const smoothVideoTime = useRef(0);
    const hasMetadata = useRef(false);

    useEffect(() => {
        const video = videoRef.current;
        if (!video) return;

        // ── Block all natural playback ──────────────────────────────────────
        const blockPlay = () => { video.pause(); };
        video.addEventListener("play", blockPlay);
        video.pause();

        // ── GPU acceleration hints ──────────────────────────────────────────
        video.style.willChange = "transform";
        video.style.transform = "translateZ(0)";
        video.style.backfaceVisibility = "hidden";

        // ── Metadata listener ───────────────────────────────────────────────
        const onMeta = () => { hasMetadata.current = true; };
        if (video.readyState >= 1) {
            hasMetadata.current = true;
        } else {
            video.addEventListener("loadedmetadata", onMeta);
        }

        // ── Scroll listener (ONLY updates target, never currentTime) ────────
        const onScroll = () => {
            const scrollTop = window.scrollY;
            const maxScroll =
                document.documentElement.scrollHeight - window.innerHeight;
            if (maxScroll > 0) {
                targetScrollProgress.current = Math.min(
                    Math.max(scrollTop / maxScroll, 0),
                    1
                );
            }
        };

        window.addEventListener("scroll", onScroll, { passive: true });
        onScroll(); // initialise immediately on mount

        // ── GSAP Ticker: Master animation loop ──────────────────────────────
        // lagSmoothing(0) prevents a giant seek jump when the user switches tabs
        gsap.ticker.lagSmoothing(0);
        gsap.ticker.fps(60);

        const tick = () => {
            // LAYER 1: Smooth scroll progress (heavy inertia, cinematic feel)
            currentScrollProgress.current +=
                (targetScrollProgress.current - currentScrollProgress.current) *
                0.05;

            if (!hasMetadata.current) return;
            const duration = video.duration;
            if (!duration || isNaN(duration)) return;

            // LAYER 2: Smooth video time (prevents hard browser decode jumps)
            targetVideoTime.current = currentScrollProgress.current * duration;
            smoothVideoTime.current +=
                (targetVideoTime.current - smoothVideoTime.current) * 0.12;

            // Only write to the DOM when the delta is meaningful
            // Micro-seeks (<5ms) cause browser jitter without visual benefit
            if (
                Math.abs(video.currentTime - smoothVideoTime.current) > 0.005
            ) {
                video.currentTime = smoothVideoTime.current;
            }
        };

        gsap.ticker.add(tick);

        return () => {
            gsap.ticker.remove(tick);
            window.removeEventListener("scroll", onScroll);
            video.removeEventListener("play", blockPlay);
            video.removeEventListener("loadedmetadata", onMeta);
        };
    }, [videoRef]);
}

