export interface EvalScore {
    relevance: number; // 0-1
    safety: number; // 0-1
    goalAlignment: number; // 0-1
    hallucinationRisk: number; // 0-1
}

/**
 * AI Evaluation Infrastructure
 * Provides self-scoring and automated quality metrics for AI responses.
 * This is used to protect the platform as prompts and models evolve.
 */
export class EvalService {
    /**
     * Heuristic-based evaluation (can be upgraded to LLM-as-a-judge)
     */
    public static async evaluateResponse(
        message: string,
        response: string,
        intent: string,
        toolData?: any
    ): Promise<EvalScore> {
        let hallucinationRisk = 0;
        let goalAlignment = 0.5;

        // 1. Hallucination Check (Basic check: If tool returned data, is it in the response?)
        if (toolData?.products && toolData.products.length > 0) {
            const firstProduct = toolData.products[0].name.toLowerCase();
            if (!response.toLowerCase().includes(firstProduct)) {
                hallucinationRisk += 0.3; // AI ignored tool data
            }
        }

        // 2. Goal Alignment (Does it push towards checkout?)
        if (intent === "product_search" && (response.includes("cart") || response.includes("buy"))) {
            goalAlignment += 0.3;
        }

        const score = {
            relevance: 1.0, // Placeholder
            safety: 1.0,
            goalAlignment: Math.min(goalAlignment, 1),
            hallucinationRisk
        };

        if (hallucinationRisk > 0.5 || goalAlignment < 0.3) {
            logger.warn(`[EVAL] Low quality AI response detected`, { intent, score });
        }

        return score;
    }
}

import { prisma } from "../prisma";
import { logger } from "../logger";

export interface PredictionResult {
    conversionProbability: number; // 0 to 1
    churnRisk: number; // 0 to 1
    intentStrength: number; // 0 to 1
    recommendedAction: "nurture" | "close" | "discount" | "support";
}

/**
 * Predictive Intelligence Engine
 * Evaluates real-time session data, historical patterns, and intent signals
 * to forecast commerce outcomes and guide orchestrator decisions.
 */
export class PredictiveEngine {
    public static async evaluateSession(
        projectId: string,
        customerId: string,
        history: any[],
        cart: any
    ): Promise<PredictionResult> {
        let intentStrength = 0;
        let conversionProbability = 0;
        let churnRisk = 0;

        // 1. Evaluate Intent Strength (Message count, product queries)
        const productQueries = history.filter(h => h.message.toLowerCase().includes("camera") || h.message.toLowerCase().includes("price")).length;
        intentStrength = Math.min(productQueries * 0.2, 1);

        // 2. Evaluate Conversion Probability (Cart contents, checkout progress)
        if (cart && cart.items.length > 0) {
            conversionProbability += 0.4;
            if (cart.subtotal > 100) conversionProbability += 0.2;
        }

        // 3. Evaluate Churn Risk (Length of history vs inactivity)
        if (history.length > 10 && !cart?.items.length) {
            churnRisk += 0.5; // Circular conversation without intent
        }

        // 4. Recommend Action
        let recommendedAction: PredictionResult["recommendedAction"] = "nurture";

        if (conversionProbability > 0.6) {
            recommendedAction = "close";
        } else if (churnRisk > 0.4 && intentStrength > 0.3) {
            recommendedAction = "discount";
        } else if (intentStrength < 0.2) {
            recommendedAction = "support";
        }

        logger.info(`[PREDICTIVE] Session evaluated`, { 
            projectId, 
            customerId, 
            conversionProbability, 
            recommendedAction 
        });

        return {
            conversionProbability,
            churnRisk,
            intentStrength,
            recommendedAction
        };
    }
}

import { AsyncLocalStorage } from "async_hooks";
import { trace } from "@opentelemetry/api";

export const logContext = new AsyncLocalStorage<{ correlationId: string }>();

type LogLevel = "info" | "warn" | "error" | "debug";

function format(level: LogLevel, message: string, meta?: any) {
    const context = logContext.getStore();
    const correlationId = context?.correlationId || "system";

    // Extract OTel trace context
    const span = trace.getActiveSpan();
    const spanContext = span?.spanContext();
    const traceId = spanContext?.traceId;
    const spanId = spanContext?.spanId;

    const entry = {
        timestamp: new Date().toISOString(),
        level,
        correlationId,
        traceId,
        spanId,
        message,
        ...meta,
    };

    if (process.env.NODE_ENV === "production") {
        return JSON.stringify(entry);
    } else {
        const color = level === "error" ? "\x1b[31m" : level === "warn" ? "\x1b[33m" : "\x1b[32m";
        return `${color}[${level.toUpperCase()}]\x1b[0m [${correlationId}] ${message} ${meta ? JSON.stringify(meta) : ""}`;
    }
}

export const logger = {
    info: (msg: string, meta?: any) => console.log(format("info", msg, meta)),
    warn: (msg: string, meta?: any) => console.warn(format("warn", msg, meta)),
    error: (msg: string, meta?: any) => console.error(format("error", msg, meta)),
    debug: (msg: string, meta?: any) => {
        if (process.env.NODE_ENV !== "production") {
            console.debug(format("debug", msg, meta));
        }
    },
};

import { v4 as uuidv4 } from "uuid";
import { logContext } from "../logger";

/**
 * Wraps a function in an observability context, ensuring a correlation ID
 * exists and is propagated through the logger.
 */
export async function withObservability<T>(
    correlationId: string | null,
    fn: () => Promise<T>
): Promise<T> {
    const id = correlationId || uuidv4();
    return await logContext.run({ correlationId: id }, fn);
}

/**
 * Higher-order function for Next.js API routes to inject observability.
 */
export function observeApi(handler: Function) {
    return async (req: Request, ...args: any[]) => {
        const correlationId = req.headers.get("x-correlation-id");
        return await withObservability(correlationId, () => handler(req, ...args));
    };
}

