// Agent Safety & Policy Framework

export enum RiskLevel {
    LOW = "LOW",
    MEDIUM = "MEDIUM",
    HIGH = "HIGH"
}

export interface SafetyPolicy {
    maxDiscount: number;
    maxQuantity: number;
    requireApproval: boolean;
    confirmationRequired: string[];
    restrictedTools: string[];
}

export const DEFAULT_POLICY: SafetyPolicy = {
    maxDiscount: 0.20,
    maxQuantity: 10,
    requireApproval: false,
    confirmationRequired: ["checkout_start", "order_create", "apply_discount"],
    restrictedTools: ["delete_customer", "override_price"]
};

export function getRiskLevel(tool: string): RiskLevel {
    const riskMap: Record<string, RiskLevel> = {
        "product_search": RiskLevel.LOW,
        "cart_view": RiskLevel.LOW,
        "cart_add": RiskLevel.MEDIUM,
        "cart_clear": RiskLevel.MEDIUM,
        "checkout_start": RiskLevel.HIGH,
        "order_status": RiskLevel.MEDIUM,
        "courier_track": RiskLevel.LOW
    };
    return riskMap[tool] || RiskLevel.MEDIUM;
}

export async function validateAction(tool: string, args: any, customPolicy?: SafetyPolicy) {
    const context = projectContext.getStore();
    const projectId = context?.projectId;

    let policy = customPolicy || DEFAULT_POLICY;

    if (projectId) {
        try {
            const project = await prisma.project.findUnique({
                where: { id: projectId },
                select: {
                    maxDiscount: true,
                    maxQuantity: true,
                    requireApproval: true,
                    confirmationRequired: true,
                    restrictedTools: true
                }
            });
            if (project) {
                policy = project as SafetyPolicy;
            }
        } catch (err) {
            console.error("[SAFETY] Failed to fetch per-tenant policy, falling back to default.", err);
        }
    }

    if (policy.restrictedTools.includes(tool)) {
        return { valid: false, reason: "Tool is restricted under current policy." };
    }

    if (args.quantity && args.quantity > policy.maxQuantity) {
        return { valid: false, reason: `Quantity ${args.quantity} exceeds safety limit of ${policy.maxQuantity}.` };
    }

    if (tool === "apply_discount" && args.discount > policy.maxDiscount) {
        return { valid: false, reason: `Discount ${args.discount * 100}% exceeds safety limit of ${policy.maxDiscount * 100}%.` };
    }

    return { valid: true };
}

export interface QualificationState {
    hasBudget: boolean;
    hasUseCase: boolean;
    hasStylePreference: boolean;
    hasTechnicalSpecs: boolean;
}

export interface QualificationGap {
    field: keyof QualificationState;
    question: string;
}

const QUESTIONS: QualificationGap[] = [
    { field: "hasUseCase", question: "What will you mainly use this for? (e.g., professional work, casual use, or a specific hobby?)" },
    { field: "hasBudget", question: "Do you have a specific budget range in mind for this?" },
    { field: "hasStylePreference", question: "Any preferences regarding style, color, or brand?" },
];

/**
 * Analyzes the current profile and history to find what's missing 
 * to provide an "elite" recommendation.
 */
export function getNextQualificationQuestion(profile: any): string | null {
    if (!profile) return QUESTIONS[0].question;

    for (const gap of QUESTIONS) {
        if (!profile[gap.field]) {
            return gap.question;
        }
    }

    return null;
}

/**
 * Heuristic to determine if we should stop searching and start qualifying.
 */
export function shouldQualify(message: string, resultsCount: number): boolean {
    // If user query is too broad (e.g. "I need a laptop") and we have too many results
    const genericTerms = ["need", "want", "looking for", "show me"];
    const isGeneric = genericTerms.some(t => message.toLowerCase().startsWith(t)) && message.split(' ').length < 5;

    return isGeneric || resultsCount > 10;
}

