export type RecoveryTriggerType = "hesitation" | "cart_abandonment" | "price_sensitivity";

/**
 * Handles proactive autonomous interventions based on real-time events.
 */
export async function handleRecoveryTrigger(
    type: RecoveryTriggerType, 
    payload: any
): Promise<void> {
    const { projectId, sessionId, userId, context } = payload;

    // In a real system, we'd fetch the active cart and profile
    // const profile = await getCustomerProfile(projectId, userId);

    let systemPrompt = `You are an elite autonomous sales agent. 
You are proactively reaching out to the customer because a specific behavioral trigger fired: ${type}.`;

    if (type === "hesitation") {
        systemPrompt += `\nThe customer has been hesitating on the current selection. Offer to narrow down the choices or ask a clarifying question about their core priority (e.g. battery life vs performance). Keep it short and helpful.`;
    } else if (type === "cart_abandonment") {
        systemPrompt += `\nThe customer added items to the cart but hasn't proceeded. Offer a gentle nudge, perhaps highlight a low stock warning for one of the items, or ask if they have any questions about the checkout process.`;
    } else if (type === "price_sensitivity") {
        systemPrompt += `\nThe customer seems hesitant due to price (e.g. asked for discounts, viewed cheaper alternatives repeatedly). Offer to find similar options under their budget or explain the long-term value of the current item.`;
    }

    try {
        const completion = await groq.chat.completions.create({
            model: "llama-3.1-8b-instant",
            messages: [
                { role: "system", content: systemPrompt },
                { role: "user", content: `Context: ${JSON.stringify(context || {})}\nGenerate the proactive message:` }
            ],
            temperature: 0.7,
            max_completion_tokens: 150
        });

        const recoveryMessage = completion.choices[0]?.message?.content;

        console.log(`[RECOVERY ENGINE] Generated proactive message for ${sessionId}:`, recoveryMessage);

        // Emit to SSE stream via OmniBus
        omniBus.emitOmni(OmniEvent.AUTONOMOUS_MESSAGE_GENERATED, {
            sessionId,
            message: recoveryMessage,
            data: { type: "autonomous_intervention", trigger: type }
        });

    } catch (error) {
        console.error(`[RECOVERY ENGINE] Failed to generate recovery message for ${type}`, error);
    }
}

import { omniBus, OmniEvent } from "../events";

export interface SessionState {
    sessionId: string;
    projectId: string;
    userId: string;
    startTime: number;
    lastActivity: number;
    viewedProducts: Set<number>;
    comparedProducts: Set<number>;
    hesitationWarnings: number;
}

// In-memory store for active sessions (in production, use Redis)
const activeSessions = new Map<string, SessionState>();

export function getOrCreateSession(projectId: string, sessionId: string, userId: string): SessionState {
    if (!activeSessions.has(sessionId)) {
        activeSessions.set(sessionId, {
            sessionId,
            projectId,
            userId,
            startTime: Date.now(),
            lastActivity: Date.now(),
            viewedProducts: new Set(),
            comparedProducts: new Set(),
            hesitationWarnings: 0
        });
    }
    return activeSessions.get(sessionId)!;
}

export function trackActivity(sessionId: string, type: "ping" | "view" | "compare", data?: any) {
    const session = activeSessions.get(sessionId);
    if (!session) return;

    session.lastActivity = Date.now();

    if (type === "view" && data?.productId) {
        session.viewedProducts.add(data.productId);
        omniBus.emitOmni(OmniEvent.PRODUCT_VIEWED, { sessionId, productId: data.productId });
    }

    if (type === "compare" && data?.productIds) {
        data.productIds.forEach((id: number) => session.comparedProducts.add(id));
        omniBus.emitOmni(OmniEvent.PRODUCT_COMPARED, { sessionId, productIds: data.productIds });
    }
}

// Hesitation check loop - only run in production/development, not during build
if (process.env.NEXT_PHASE !== "phase-production-build" && typeof window === "undefined") {
    setInterval(() => {
        const now = Date.now();
        for (const [sessionId, session] of activeSessions.entries()) {
            const inactiveTime = now - session.lastActivity;

            // If inactive for 30 seconds but has viewed products (simulate hesitation)
            if (inactiveTime > 30000 && inactiveTime < 60000 && session.viewedProducts.size > 0) {
                if (session.hesitationWarnings === 0) {
                    session.hesitationWarnings++;
                    omniBus.emitOmni(OmniEvent.SESSION_HESITATION, { 
                        sessionId, 
                        projectId: session.projectId,
                        userId: session.userId,
                        context: { viewedProducts: Array.from(session.viewedProducts) }
                    });
                }
            }

            // Cleanup very old sessions (e.g. 1 hour)
            if (inactiveTime > 3600000) {
                activeSessions.delete(sessionId);
            }
        }
    }, 10000); // Check every 10 seconds
}

import { prisma } from "../prisma";
import { OmniEvent } from "../events";

export interface AnalyticsData {
    roi: {
        totalRevenue: number;
        aiAssistedRevenue: number;
        tokenCostUsd: number;
        roiMultiplier: number;
    };
    signals: {
        avgPurchaseIntent: number;
        avgAbandonmentRisk: number;
        accelerateCount: number;
        rescueCount: number;
        nurtureCount: number;
        totalSessions: number;
    };
    topEvents: {
        name: string;
        count: number;
    }[];
}

export class AnalyticsService {
    public static async getProjectStats(projectId: string): Promise<AnalyticsData> {
        const [checkouts, carts, usage, events] = await Promise.all([
            prisma.checkoutSession.findMany({ where: { projectId } }),
            prisma.cart.findMany({ where: { projectId }, include: { items: true } }),
            prisma.usage.findMany({ where: { projectId } }),
            prisma.systemEvent.findMany({ 
                where: { 
                    projectId,
                    type: { in: [OmniEvent.OUTCOME_SIGNAL, OmniEvent.PRODUCT_VIEWED, OmniEvent.CART_UPDATED, OmniEvent.CHECKOUT_STARTED, OmniEvent.ORDER_CREATED, OmniEvent.CART_ABANDONED_POTENTIAL] }
                } 
            })
        ]);

        const completed = checkouts.filter(c => c.status === "completed");
        const totalRevenue = carts
            .filter(c => c.status === "converted")
            .reduce((sum, c) => sum + c.subtotal, 0);

        // Assume AI assisted roughly 80% of revenue for simplicity if they interacted
        const aiAssistedRevenue = totalRevenue * 0.8; 

        const totalTokens = usage.reduce((sum, u) => sum + u.tokens, 0);
        const tokenCostUsd = (totalTokens / 1000) * 0.01; 
        const roiMultiplier = tokenCostUsd > 0 ? aiAssistedRevenue / tokenCostUsd : 0;

        // Predictive Signals
        const outcomeSignals = events.filter(e => e.type === OmniEvent.OUTCOME_SIGNAL).map(e => e.payload as any);
        const totalSessions = checkouts.length || 1; // fallback to avoid NaN

        let totalIntent = 0;
        let totalRisk = 0;
        let accelerateCount = 0;
        let rescueCount = 0;
        let nurtureCount = 0;

        for (const signal of outcomeSignals) {
            totalIntent += signal.conversionProbability || 0;
            totalRisk += signal.churnRisk || 0;
            if (signal.recommendedAction === "close") accelerateCount++;
            if (signal.recommendedAction === "discount") rescueCount++;
            if (signal.recommendedAction === "nurture") nurtureCount++;
        }

        const avgPurchaseIntent = outcomeSignals.length > 0 ? totalIntent / outcomeSignals.length : 0;
        const avgAbandonmentRisk = outcomeSignals.length > 0 ? totalRisk / outcomeSignals.length : 0;

        // Top Events
        const eventCounts: Record<string, number> = {};
        for (const e of events) {
            if (e.type !== OmniEvent.OUTCOME_SIGNAL) {
                eventCounts[e.type] = (eventCounts[e.type] || 0) + 1;
            }
        }

        const topEvents = Object.entries(eventCounts)
            .map(([name, count]) => ({ name, count }))
            .sort((a, b) => b.count - a.count)
            .slice(0, 5);

        // Fallback for visual testing if no events exist
        if (topEvents.length === 0) {
            topEvents.push({ name: "product.viewed", count: 12 });
            topEvents.push({ name: "cart.updated", count: 4 });
            topEvents.push({ name: "checkout.started", count: 1 });
        }

        return {
            roi: {
                totalRevenue,
                aiAssistedRevenue,
                tokenCostUsd,
                roiMultiplier
            },
            signals: {
                avgPurchaseIntent,
                avgAbandonmentRisk,
                accelerateCount,
                rescueCount,
                nurtureCount,
                totalSessions
            },
            topEvents
        };
    }
}

import { detectIntent } from "../../intent";
import { supervisorRoute } from "../../agents/supervisor";
import { runSalesAgent } from "../../agents/sales-agent";
import { evaluateConfidence } from "../../commerce/confidence";
import { reflectOnInteraction } from "../../reflection";
import { upsertCustomerProfile, saveMessage } from "../../memory";
import { evaluateStrategy } from "../../strategy";
import { assembleSystemPrompt } from "../../prompts";
import { getGoalDirective } from "../../goals";
import { groq } from "../../groq";
import { logger } from "../../logger";
import { OrchestratorContext, OrchestratorResponse, ConversationContext } from "./types";
import { ContextAssembler } from "./context-assembler";
import { ToolExecutionEngine } from "./tool-engine";
import { checkTenantRateLimit } from "../../ratelimit";
import { withResilience } from "../../resilience";
import { validateInput, sanitizeOutput } from "../../security";
import { withObservability } from "../../middleware/observability";
import { PredictiveEngine } from "../../intelligence/predictive";
import { EvalService } from "../../intelligence/evaluator";
import { omniBus, OmniEvent } from "../../events";

export class OrchestratorService {
    public static async process(ctx: OrchestratorContext): Promise<OrchestratorResponse> {
        const { projectId, userId, sessionId, message, channel, metadata } = ctx;
        const correlationId = metadata?.correlationId || null;

        return await withObservability(correlationId, async () => {
            // 0. Security & Rate Limiting
            const security = validateInput(message);
            if (!security.safe) {
                return { content: "I cannot process this request due to security policies.", intent: "security_violation" };
            }

            const ratelimit = await checkTenantRateLimit(projectId);
            if (!ratelimit.success) {
                logger.warn(`[ORCHESTRATOR] Rate limit exceeded for project`, { projectId });
                return {
                    content: "I'm receiving too many requests from your account right now. Please wait a moment and try again.",
                    intent: "rate_limit_exceeded"
                };
            }

            return await withResilience(async () => {
                try {
                    // 1. Assemble Context
                    const convCtx = await ContextAssembler.assemble(ctx);
                    const { profile, history, cart, checkout, knowledge, project } = convCtx;

                    // 1b. Predictive Intelligence
                    const prediction = await PredictiveEngine.evaluateSession(projectId, userId, history, cart);
                    omniBus.emitOmni(OmniEvent.OUTCOME_SIGNAL, { 
                        ...prediction,
                        sessionId,
                        projectId,
                        timestamp: Date.now()
                    });

                    // 2. Intent Detection
                    const intent = await detectIntent(message);
                    logger.info(`[ORCHESTRATOR] Detected intent: ${intent.intent}`, { projectId, sessionId });

                    // 3. Confidence Check
                    const confidence = await evaluateConfidence(message, history);
                    if (confidence.score < 0.6 && confidence.missingInformation.length > 0) {
                        const clarification = `I want to make sure I get this exactly right for you. Could you clarify: ${confidence.missingInformation.join(", ")}?`;
                        await saveMessage(projectId, sessionId, userId, message, clarification);
                        return { content: clarification, intent: "clarification_request" };
                    }

                    // 4. Tool Execution
                    const toolResult = await ToolExecutionEngine.execute(intent, message, convCtx, userId);

                    // 5. Routing & Agent Execution
                    const routedRole = await supervisorRoute({
                        userMessage: message,
                        history,
                        cart,
                        profile,
                        channel,
                        wcConfig: {
                            storeUrl: project.wooCommerceStoreUrl,
                            consumerKey: project.wooCommerceKey,
                            consumerSecret: project.wooCommerceSecret
                        }
                    });

                    let responseContent = "";
                    if (routedRole === "sales" || routedRole === "comparison") {
                        responseContent = await runSalesAgent({
                            userMessage: message,
                            history,
                            cart,
                            profile,
                            channel,
                            wcConfig: {} 
                        }, toolResult.text);
                    } else {
                        // Default Support/General Agent
                        const strategy = evaluateStrategy(profile, cart);
                        const systemPrompt = assembleSystemPrompt({
                            customer: profile,
                            cart,
                            checkout,
                            channel,
                            strategy
                        });

                        const systemContent = [
                            systemPrompt,
                            getGoalDirective(),
                            history.length ? `History:\n${history.map(e => `User: ${e.message}\nAssistant: ${e.response}`).join("\n")}` : "",
                            knowledge.length ? `Knowledge:\n${knowledge.join("\n")}` : "",
                            toolResult.text ? `Current Context:\n${toolResult.text}` : "",
                        ].filter(Boolean).join("\n\n");

                        const stream = await groq.chat.completions.create({
                            model: "llama-3.3-70b-versatile",
                            messages: [{ role: "system", content: systemContent }, { role: "user", content: message }],
                            max_completion_tokens: 500,
                            temperature: 0.7,
                            stream: !!ctx.onStream
                        });

                        if (ctx.onStream && (stream as any)[Symbol.asyncIterator]) {
                           for await (const chunk of stream as any) {
                               const content = chunk.choices[0]?.delta?.content || "";
                               if (content) {
                                   responseContent += content;
                                   ctx.onStream(content);
                               }
                           }
                        } else {
                            const completion = stream as any;
                            responseContent = completion.choices[0]?.message?.content || "I'm having trouble formulating a response.";
                        }
                    }

                    // 6. Persistence & Memory
                    await Promise.all([
                        saveMessage(projectId, sessionId, userId, message, responseContent),
                        this.performReflection(projectId, userId, message, responseContent, history, profile)
                    ]);

                    // 7. AI Quality Evaluation
                    const evaluation = await EvalService.evaluateResponse(message, responseContent, intent.intent, toolResult.data);

                    return {
                        content: sanitizeOutput(responseContent),
                        data: {
                            ...toolResult.data,
                            prediction,
                            evaluation
                        },
                        intent: intent.intent
                    };

                } catch (err) {
                    logger.error("[ORCHESTRATOR] Critical execution failure", { error: err, projectId, userId });
                    return {
                        content: "I'm sorry, I encountered a technical problem and cannot process your request right now. Please try again in a moment.",
                        intent: "error"
                    };
                }
            });
        });
    }

    private static async performReflection(
        projectId: string, 
        userId: string, 
        message: string, 
        response: string, 
        history: any[],
        profile: any
    ) {
        try {
            const reflection = await reflectOnInteraction(message, response, history);
            if (reflection?.learned_preferences) {
                const currentPrefs = profile?.preferences || {};
                await upsertCustomerProfile(projectId, userId, {
                    preferences: {
                        ...currentPrefs,
                        ...reflection.learned_preferences
                    }
                });
            }
        } catch (err) {
            logger.error("[ORCHESTRATOR] Reflection failed", { error: err });
        }
    }
}

import { z } from "zod";
import { 
    searchProducts, 
    getProduct, 
    getOrder, 
    formatOrderSummary, 
    normalizeWCProduct
} from "../../woocommerce";
import { addToCart, getCart } from "../../cart";
import { generateProductComparison } from "../../commerce/comparison";
import { trackActivity } from "../../sales/session";
import { ConversationContext } from "./types";

const ProductSearchSchema = z.object({
    product_query: z.string().min(2).max(100)
});

const OrderLookupSchema = z.object({
    order_id: z.string().regex(/^\d+$/)
});

const CartActionSchema = z.object({
    product_id: z.coerce.number().positive().optional(),
    quantity: z.coerce.number().int().min(1).max(10).optional(),
    product_query: z.string().optional()
});

export interface ToolResult {
    text: string;
    data?: any;
}

export class ToolExecutionEngine {
    public static async execute(
        intent: any, 
        message: string, 
        ctx: ConversationContext,
        userId: string
    ): Promise<ToolResult> {
        const { project } = ctx;
        const wcConfig = {
            storeUrl: project.wooCommerceStoreUrl || "",
            consumerKey: project.wooCommerceKey || "",
            consumerSecret: project.wooCommerceSecret || "",
        };

        try {
            switch (intent.intent) {
                case "product_search": {
                    const params = ProductSearchSchema.parse(intent.entities);
                    const products = await searchProducts(params.product_query, wcConfig);
                    if (!products.length) return { text: "No products found matching your query." };

                    return {
                        text: `I found these items for you: ${products.map(p => p.name).join(", ")}`,
                        data: { 
                            type: "product_list", 
                            products: products.map(normalizeWCProduct) 
                        }
                    };
                }

                case "add_to_cart": {
                    const params = CartActionSchema.parse(intent.entities);
                    if (!params.product_id) return { text: "Which product would you like to add?" };

                    const product = await getProduct(params.product_id, wcConfig);
                    if (!product) return { text: "I couldn't find that product." };

                    const cart = await addToCart(ctx.project.id, userId, {
                        productId: product.id,
                        name: product.name,
                        price: parseFloat(product.price),
                        quantity: params.quantity || 1,
                        image: product.images?.[0]?.src
                    });

                    return { 
                        text: `Added ${product.name} to your cart. You now have ${cart.items.length} items.`,
                        data: { cart }
                    };
                }

                case "view_cart": {
                    CartActionSchema.parse(intent.entities);
                    const cart = await getCart(project.id, userId);
                    if (!cart.items.length) return { text: "Your cart is empty." };
                    return {
                        text: `🛒 **Your Cart** Total: **${cart.subtotal.toFixed(2)}**.`,
                        data: { type: "cart_summary", cart }
                    };
                }

                case "order_status": {
                    const params = OrderLookupSchema.parse(intent.entities);
                    const order = await getOrder(params.order_id, wcConfig);
                    return {
                        text: order ? formatOrderSummary(order) : "Order not found.",
                        data: { order }
                    };
                }

                case "comparison_request": {
                    const params = CartActionSchema.parse(intent.entities);
                    const query = params.product_query ?? message;
                    const products = await searchProducts(query, wcConfig);
                    if (products.length < 2) return { text: "I need at least two products to compare." };

                    const comparison = await generateProductComparison(products[0].id, products[1].id, wcConfig);
                    if (!comparison) return { text: "I couldn't generate a comparison at this time." };

                    trackActivity(userId, "compare", { productIds: [products[0].id, products[1].id] });

                    return {
                        text: `Here is a comparison between **${products[0].name}** and **${products[1].name}**:`,
                        data: { type: "product_comparison", comparison }
                    };
                }

                default:
                    return { text: "" };
            }
        } catch (err) {
            if (err instanceof z.ZodError) {
                console.warn("[TOOL] Contract validation failed", { error: (err as any).errors, intent: intent.intent });
                return { text: "I'm sorry, I couldn't process that because some information was missing or malformed. Could you try being more specific?" };
            }
            console.error("[TOOL] Execution failure", { error: err, intent: intent.intent });
            return { text: "I encountered a technical problem while trying to fetch that information." };
        }
    }
}

