export interface NormalizedProduct {
    id: string;
    sourceId: number;
    name: string;
    description: string;
    price: number;
    formattedPrice: string;
    currency: string;
    imageUrl: string;
    inStock: boolean;
    stockQuantity: number;
    url: string;
    attributes: Record<string, string>;
}

export function normalizeWCProduct(p: WCProduct): NormalizedProduct {
    return {
        id: `wc_${p.id}`,
        sourceId: p.id,
        name: p.name,
        description: p.short_description.replace(/<[^>]*>?/gm, ""), // Strip HTML
        price: parseFloat(p.price),
        formattedPrice: `$${p.price}`,
        currency: "USD",
        imageUrl: p.images?.[0]?.src || "",
        inStock: p.stock_status === "instock",
        stockQuantity: p.stock_quantity ?? 0,
        url: p.permalink,
        attributes: {} // Could be expanded to include WC attributes
    };
}

export async function getEnrichedProduct(productId: number, config: WooCommerceConfig): Promise<NormalizedProduct | null> {
    const product = await getProduct(productId, config);
    if (!product) return null;
    return normalizeWCProduct(product);
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { jwtVerify } from "jose";

const SECRET = new TextEncoder().encode(process.env.JWT_SECRET || "default_secret_neural_link");

export async function middleware(request: NextRequest) {
    const { pathname } = request.nextUrl;

    // Public routes
    if (
        pathname === "/" || 
        pathname.startsWith("/login") || 
        pathname.startsWith("/register") || 
        pathname.startsWith("/forgot-password") || 
        pathname.startsWith("/verify") ||
        pathname.startsWith("/api/auth") ||
        pathname.startsWith("/api/webhooks") ||
        pathname.includes(".") // static files
    ) {
        return NextResponse.next();
    }

    const token = request.cookies.get("token")?.value || request.headers.get("authorization")?.split(" ")[1];

    if (!token) {
        return NextResponse.redirect(new URL("/login", request.url));
    }

    try {
        const { payload } = await jwtVerify(token, SECRET);

        // RBAC logic example
        if (pathname.startsWith("/admin") && payload.role !== "ADMIN" && payload.role !== "OWNER") {
            return NextResponse.redirect(new URL("/dashboard", request.url));
        }

        const response = NextResponse.next();
        return response;
    } catch (e) {
        return NextResponse.redirect(new URL("/login", request.url));
    }
}

